from typing import List

def solve(grid: List[List[int]], start: int) -> List[List[int]]:
    # Define movements
    movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Define the heuristic function for A*
    def heuristic(state: int, goal: int):
        return abs(state % 5 - goal % 5) + abs(state // 5 - goal // 5)

    # Function to reconstruct path
    def reconstruct_path(came_from, current_state):
        path = [current_state]
        while current_state in came_from:
            current_state = came_from[current_state]
            path.insert(0, current_state)
        return path

    # Define the A* algorithm function
    def a_star(grid: List[List[int]], start: int, goal: int) -> List[List[int]]:
        open_set = {start}
        came_from = {}
        g_score = {state: float('inf') for row in grid for state in range(len(row))}
        g_score[start] = 0
        f_score = {state: float('inf') for row in grid for state in range(len(row))}
        f_score[start] = heuristic(start, goal)

        while open_set:
            current_state = min(open_set, key=lambda x: f_score[x])
            if current_state == goal:
                return reconstruct_path(came_from, current_state)
            open_set.remove(current_state)

            for movement in movements:
                new_x, new_y = current_state // 5 + movement[0], current_state % 5 + movement[1]
                if 0 <= new_x < len(grid) and 0 <= new_y < len(grid[0]) and grid[new_x][new_y] != 'X':
                    new_state = new_x * 5 + new_y
                    tentative_g_score = g_score[current_state] + 1

                    if new_state not in open_set or tentative_g_score < g_score[new_state]:
                        came_from[new_state] = current_state
                        g_score[new_state] = tentative_g_score
                        f_score[new_state] = tentative_g_score + heuristic(new_state, goal)
                        open_set.add(new_state)

        return None

    # Call the A* function and return the path
    grid_2d = [[cell for cell in row] for row in grid]
    goal_index = goal % 5 + (goal // 5) * 5
    grid[goal_index // 5][goal_index % 5] = '_'
    return a_star(grid_2d, start, goal_index)[1:]

